// Recurrence of any task (`recurrence` on POST/PATCH /tasks, migration 0019): the task becomes the first
// occurrence of a recurring task of origin `task` (its client, or internal) generated by the same engine;
// its occurrences are listed as tasks and stay out of the monthly audit and the obligations blocks; the
// series is changed or ended from the task (`applyTo: 'series'`, `recurrence: null`); any member repeats
// their own tasks or their department's, the rest needs `registry`; the registry's recurring tasks are
// still managed in "Recorrentes".
// Today is pinned to 2026-10-20, a Tuesday (vitest.config.ts); 2026-11-02 (Monday) is a national holiday.

import { sql } from 'drizzle-orm';
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { occurrencesInCompetence, type RecurringSchedule } from '@effinance/shared';
import type { App } from '../src/app';
import { executeRows } from '../src/lib/sql';
import { admin, createTestApp, resetDb, type Client } from './helpers';
import { createClient, office, workspaceOf } from './task-helpers';

let app: App;
beforeAll(async () => {
  app = await createTestApp();
});
afterAll(async () => {
  delete process.env.EFFINANCE_NOW;
  await app.close();
});
beforeEach(async () => {
  await resetDb(app);
  process.env.EFFINANCE_NOW = '2026-10-20T15:00:00Z';
});

const rows = <T>(query: ReturnType<typeof sql>) => executeRows<T>(admin(), query);

type SeriesRow = {
  id: string;
  client_id: string | null;
  period_key: string;
  due_date: string;
  target_date: string;
  title: string;
  status: string;
  priority: string;
  start_time: string | null;
  occurrence_origin: string;
  created_by_name: string;
};

async function seriesRows(recurringTaskId: string) {
  return rows<SeriesRow>(sql`
    select id, client_id, period_key, due_date::text, target_date::text, title, status, priority, start_time, occurrence_origin, created_by_name
      from tasks where recurring_task_id = ${recurringTaskId} order by due_date, id`);
}

async function create(c: Client, body: Record<string, unknown>) {
  const res = await c.post('/tasks', body);
  expect(res.status, JSON.stringify(res.body)).toBe(201);
  return res.body;
}

const businessDays = (competence: string, from: string) =>
  occurrencesInCompetence({ period: 'daily', dueDay: 1, dueMonth: null, targetDaysBefore: 0, nonBusinessDayRule: 'skip', referenceOffset: 0, startDate: from } satisfies RecurringSchedule, competence).length;

describe('task recurrence: creating and listing', () => {
  it('an internal daily task: the task is the first occurrence, the next ones are tasks, out of the audit and the obligations', async () => {
    const { ana, carla, fiscal } = await office(app);
    const ws = await workspaceOf(ana);
    const task = await create(carla, {
      title: 'Conferir caixa',
      description: 'Somar o caixa do dia',
      assigneeId: carla.userId,
      dueDate: '2026-10-21',
      priority: 'high',
      startTime: '09:00',
      endTime: '09:30',
      recurrence: { frequency: 'daily' },
    });
    expect(task).toMatchObject({
      title: 'Conferir caixa',
      kind: 'recurring',
      dueDate: '2026-10-21',
      client: null,
      department: { id: fiscal },
      description: 'Somar o caixa do dia',
      startTime: '09:00',
      occurrence: { origin: 'task', period: 'daily', periodKey: '2026-10-21', competence: '2026-10', assigneeSource: 'default' },
      recurrence: {
        frequency: 'daily',
        interval: 1,
        weekdays: [],
        startDate: '2026-10-21',
        ends: 'never',
        endDate: null,
        nonBusinessDayRule: 'skip',
        active: true,
        canEdit: true,
      },
      canReopen: false,
    });
    expect(task.recurrence.upcoming.map((u: any) => u.legalDueDate)).toEqual(['2026-10-21', '2026-10-22', '2026-10-23', '2026-10-26', '2026-10-27']);
    expect(task.lockedFields).toContain('title');
    const seriesId = task.occurrence.recurringTaskId;

    // Generated up to two competences ahead, every one internal, of origin `task`, with the series' fields.
    const generated = await seriesRows(seriesId);
    expect(generated).toHaveLength(businessDays('2026-10', '2026-10-21') + businessDays('2026-11', '2026-10-21') + businessDays('2026-12', '2026-10-21'));
    expect(generated.every((r) => r.client_id === null && r.occurrence_origin === 'task' && r.priority === 'high' && r.start_time === '09:00')).toBe(true);
    expect(generated[0]).toMatchObject({ id: task.id, created_by_name: 'Carla Souza' });
    expect(generated[1]!.created_by_name).toBe('Tarefa recorrente');
    const second = await carla.get(`/tasks/${generated[1]!.id}`);
    expect(second.body).toMatchObject({ description: 'Somar o caixa do dia', dueDate: '2026-10-22' });
    // Idempotent, and two internal occurrences of the same period are refused by the database.
    await carla.get('/tasks?scope=mine');
    expect(await seriesRows(seriesId)).toHaveLength(generated.length);
    const duplicate = await admin()
      .execute(sql`insert into tasks (workspace_id, title, recurring_task_id, occurrence_origin, competence, period_key, reference_month, due_date, target_date, created_by_name)
        values (${ws}, 'Dup', ${seriesId}, 'task', '2026-10', '2026-10-22', '2026-10', '2026-10-22', '2026-10-22', 'X')`)
      .then(() => null, (e: { cause?: { code?: string; constraint_name?: string } }) => e.cause);
    expect(duplicate).toMatchObject({ code: '23505', constraint_name: 'tasks_internal_occurrence_uq' });

    // The list shows them as tasks: the next 7 days (no aggregate), the rest when the month is asked.
    const mine = await carla.get('/tasks?scope=mine&pageSize=200');
    expect(mine.body.items.filter((t: any) => t.title === 'Conferir caixa').map((t: any) => t.dueDate)).toEqual([
      '2026-10-21',
      '2026-10-22',
      '2026-10-23',
      '2026-10-26',
      '2026-10-27',
    ]);
    expect(mine.body.occurrences).toEqual([]);
    expect(mine.body.summary.open).toBe(5);
    const november = await carla.get('/tasks?scope=mine&month=2026-11&pageSize=200');
    expect(november.body.items).toHaveLength(businessDays('2026-11', '2026-10-21'));
    const recurringKind = await carla.get('/tasks?kind=recurring&dueFrom=2026-10-21&dueTo=2026-10-23');
    expect(recurringKind.body.items).toHaveLength(3);

    // Start page: in "Minhas" as tasks, never in the obligations; calendar: tasks, not aggregates.
    const home = await carla.get('/tasks/home');
    expect(home.body.mine.tasks.filter((t: any) => t.title === 'Conferir caixa')).toHaveLength(5);
    expect(home.body.mine.occurrences).toEqual([]);
    expect(home.body.obligations).toMatchObject({ total: 0, items: [] });
    const calendar = await carla.get('/tasks/calendar?from=2026-10-19&to=2026-10-25&scope=mine');
    expect(calendar.body.tasks.map((t: any) => t.dueDate)).toEqual(['2026-10-21', '2026-10-22', '2026-10-23']);
    expect(calendar.body.occurrences).toEqual([]);
    const report = await carla.get('/tasks/reports?from=2026-10-01&to=2026-10-31&kind=recurring');
    expect(report.body.summary.total).toBe(businessDays('2026-10', '2026-10-21'));

    // The audit and the registry ignore it.
    const audit = await carla.get('/tasks/audit?competence=2026-10');
    expect(audit.body.columns).toEqual([]);
    expect(audit.body.summary.total).toBe(0);
    expect((await carla.get('/tasks/recurring?status=all')).body.items).toEqual([]);
    expect((await ana.get(`/tasks/recurring/${seriesId}`)).status).toBe(404);
    expect((await ana.put(`/tasks/recurring/${seriesId}`, { name: 'X', departmentId: fiscal, dueDay: 5, regimes: ['mei'] })).status).toBe(404);
    // Search: only the next open occurrence of the series.
    const search = await carla.get('/search?q=conferir');
    expect(search.body.tasks).toEqual([expect.objectContaining({ id: task.id, kind: 'recurring' })]);
  });

  it('obligation rules (target, non-business day, reference) and reopening like any task', async () => {
    const { carla } = await office(app);
    const task = await create(carla, {
      title: 'Enviar balancete',
      assigneeId: carla.userId,
      dueDate: '2026-11-15',
      recurrence: { frequency: 'monthly', targetDaysBefore: 3, nonBusinessDayRule: 'postpone', referenceOffset: 1 },
    });
    // 15/11/2026 is a Sunday (and a holiday): the legal deadline goes to Monday 16, the target 3 days before.
    expect(task).toMatchObject({
      dueDate: '2026-11-16',
      occurrence: { periodKey: '2026-11', competence: '2026-11', referenceMonth: '2026-10', targetDate: '2026-11-13' },
      recurrence: { dueDay: 15, targetDaysBefore: 3, nonBusinessDayRule: 'postpone', referenceOffset: 1 },
    });
    expect((await seriesRows(task.occurrence.recurringTaskId)).map((r) => r.due_date)).toEqual(['2026-11-16', '2026-12-15']);
    // Concluded and reopened later by its author without a reason (the audit-record rule is the registry's).
    expect((await carla.patch(`/tasks/${task.id}/status`, { status: 'done' })).status).toBe(200);
    process.env.EFFINANCE_NOW = '2026-10-20T17:00:00Z';
    const detail = await carla.get(`/tasks/${task.id}`);
    expect(detail.body.canReopen).toBe(true);
    expect((await carla.patch(`/tasks/${task.id}/status`, { status: 'todo' })).status).toBe(200);
  });

  it('refuses a start too far back, a rule without occurrences and a client not active then', async () => {
    const { ana, carla } = await office(app);
    const future = await createClient(ana, { tradeName: 'Futura', contractStartDate: '2027-03-01' });
    const tooOld = await carla.post('/tasks', { title: 'X', assigneeId: carla.userId, dueDate: '2026-08-10', recurrence: { frequency: 'monthly' } });
    expect(tooOld).toMatchObject({ status: 422, body: { message: 'A recorrência pode começar a partir de 01/09/2026.' } });
    const none = await carla.post('/tasks', {
      title: 'X',
      assigneeId: carla.userId,
      dueDate: '2026-10-25',
      recurrence: { frequency: 'monthly', dueDay: 10, ends: 'date', endDate: '2026-11-05' },
    });
    expect(none).toMatchObject({ status: 422, body: { message: 'Essa recorrência não tem nenhuma ocorrência.' } });
    const inactive = await carla.post('/tasks', { title: 'X', clientId: future, assigneeId: carla.userId, dueDate: '2026-10-25', recurrence: { frequency: 'monthly' } });
    expect(inactive).toMatchObject({ status: 422, body: { message: 'O cliente ainda não está ativo em 10/2026.' } });
    expect(await rows(sql`select id from recurring_tasks`)).toEqual([]);
  });
});

describe('task recurrence: changing and ending it from the task', () => {
  it('weekly on Mon/Wed for 4 times; the series follows the task; a new rule moves the task; ending it cancels the rest', async () => {
    const { ana, carla } = await office(app);
    const padaria = await createClient(ana, { tradeName: 'Padaria' });
    const task = await create(carla, {
      title: 'Ligar para a Padaria',
      clientId: padaria,
      assigneeId: carla.userId,
      dueDate: '2026-10-21',
      recurrence: { frequency: 'weekly', weekdays: [3, 1], ends: 'count', count: 4 },
    });
    // Wed 21, Mon 26, Wed 28, (Mon 2 is a holiday: skipped) Wed 4.
    expect(task.recurrence).toMatchObject({ weekdays: [1, 3], ends: 'count', count: 4, endDate: '2026-11-04' });
    const seriesId = task.occurrence.recurringTaskId;
    let list = await seriesRows(seriesId);
    expect(list.map((r) => r.period_key)).toEqual(['2026-10-21', '2026-10-26', '2026-10-28', '2026-11-04']);
    expect(list.every((r) => r.client_id === padaria)).toBe(true);

    // Without `applyTo: 'series'` the series' fields stay locked; with it, the open ones follow.
    const second = list[1]!.id;
    expect((await carla.patch(`/tasks/${second}`, { title: 'Ligar' })).status).toBe(422);
    const renamed = await carla.patch(`/tasks/${second}`, { title: 'Ligar para a Padaria (vendas)', priority: 'urgent', applyTo: 'series' });
    expect(renamed.status, JSON.stringify(renamed.body)).toBe(200);
    list = await seriesRows(seriesId);
    expect(list.every((r) => r.title === 'Ligar para a Padaria (vendas)' && r.priority === 'urgent')).toBe(true);
    // Only this occurrence: like any occurrence (priority, responsible).
    expect((await carla.patch(`/tasks/${second}`, { priority: 'low' })).status).toBe(200);
    expect((await seriesRows(seriesId)).find((r) => r.id === second)!.priority).toBe('low');

    // A new rule (Tuesdays) from the first task: it moves to the nearest Tuesday, the others are canceled.
    const moved = await carla.patch(`/tasks/${task.id}`, { recurrence: { frequency: 'weekly', weekdays: [2], ends: 'count', count: 4 } });
    expect(moved.status, JSON.stringify(moved.body)).toBe(200);
    expect(moved.body).toMatchObject({ id: task.id, status: 'todo', dueDate: '2026-10-27', occurrence: { periodKey: '2026-10-27' }, recurrence: { weekdays: [2], endDate: '2026-11-17' } });
    list = await seriesRows(seriesId);
    expect(list.filter((r) => r.status === 'todo').map((r) => r.due_date)).toEqual(['2026-10-27', '2026-11-03', '2026-11-10', '2026-11-17']);
    expect(list.filter((r) => r.status === 'canceled').map((r) => r.period_key)).toEqual(['2026-10-26', '2026-10-28', '2026-11-04']);

    // Ending it at the occurrence of 3/11: the later ones are canceled, with the reason in their history.
    const nov3 = list.find((r) => r.due_date === '2026-11-03')!.id;
    const ended = await carla.patch(`/tasks/${nov3}`, { recurrence: null });
    expect(ended.status, JSON.stringify(ended.body)).toBe(200);
    expect(ended.body.recurrence).toMatchObject({ ends: 'date', endDate: '2026-11-03', count: null, active: true });
    list = await seriesRows(seriesId);
    expect(list.filter((r) => r.status === 'todo').map((r) => r.due_date)).toEqual(['2026-10-27', '2026-11-03']);
    const nov10 = list.find((r) => r.due_date === '2026-11-10')!;
    expect(nov10.status).toBe('canceled');
    const history = await carla.get(`/tasks/${nov10.id}/history`);
    expect(history.body.items[0]).toMatchObject({ kind: 'status', toStatus: 'canceled', actor: null, note: 'A recorrência foi encerrada antes desta data' });
    const mine = await carla.get(`/tasks/${task.id}/history`);
    expect(mine.body.items.some((i: any) => i.kind === 'updated' && i.fields.includes('recurrence'))).toBe(true);
  });

  it('turns a standalone task into a monthly one, switches client and internal in place, deletes an untouched series', async () => {
    const { ana, bruno, carla } = await office(app);
    const padaria = await createClient(ana, { tradeName: 'Padaria' });
    const standalone = await create(carla, { title: 'Relatório mensal', clientId: padaria, assigneeId: carla.userId, dueDate: '2026-10-30' });
    expect(standalone.recurrence).toBeNull();
    const converted = await carla.patch(`/tasks/${standalone.id}`, { recurrence: { frequency: 'monthly' } });
    expect(converted.status, JSON.stringify(converted.body)).toBe(200);
    expect(converted.body).toMatchObject({ id: standalone.id, dueDate: '2026-10-30', occurrence: { origin: 'task', periodKey: '2026-10' }, recurrence: { dueDay: 30, startDate: '2026-10-30' } });
    const seriesId = converted.body.occurrence.recurringTaskId;
    expect((await seriesRows(seriesId)).map((r) => r.due_date)).toEqual(['2026-10-30', '2026-11-30', '2026-12-30']);

    // Internal and back: the same rows change client (nothing canceled, nothing duplicated).
    expect((await carla.patch(`/tasks/${standalone.id}`, { clientId: null, applyTo: 'series' })).status).toBe(200);
    let list = await seriesRows(seriesId);
    expect(list.map((r) => [r.client_id, r.status])).toEqual([[null, 'todo'], [null, 'todo'], [null, 'todo']]);
    expect((await carla.patch(`/tasks/${standalone.id}`, { clientId: padaria, applyTo: 'series' })).status).toBe(200);
    list = await seriesRows(seriesId);
    expect(list.map((r) => [r.client_id, r.status])).toEqual([[padaria, 'todo'], [padaria, 'todo'], [padaria, 'todo']]);

    // A comment makes it history: deleting is refused; without it the whole series goes.
    const comment = await carla.post(`/tasks/${list[1]!.id}/comments`, { text: 'Cliente pediu o PDF' });
    expect((await bruno.del(`/tasks/${standalone.id}`)).status).toBe(409);
    expect((await carla.del(`/tasks/${list[1]!.id}/comments/${comment.body.id}`)).status).toBe(204);
    expect((await bruno.del(`/tasks/${standalone.id}`)).status).toBe(204);
    expect(await seriesRows(seriesId)).toEqual([]);
    expect(await rows(sql`select id from recurring_tasks where id = ${seriesId}`)).toEqual([]);

    // A process step never repeats.
    const flow = await carla.post('/tasks/flows', { title: 'Abertura', steps: [{ title: 'Documentos', relativeDays: 1 }] });
    const step = await carla.patch(`/tasks/${flow.body.task.id}`, { recurrence: { frequency: 'monthly' } });
    expect(step).toMatchObject({ status: 422, body: { message: 'Etapas de processo não se repetem.' } });
  });
});

describe('task recurrence: who may repeat what', () => {
  it('any member for their own tasks or their department; another department needs `registry`; the registry stays apart', async () => {
    const { ana, bruno, carla, fiscal, pessoal } = await office(app);
    const forbidden = 'Você só pode repetir tarefas suas ou do seu departamento.';
    const daily = { frequency: 'daily' };
    expect(await carla.post('/tasks', { title: 'Para o Bruno', assigneeId: bruno.userId, recurrence: daily })).toMatchObject({ status: 403, body: { message: forbidden } });
    expect(await carla.post('/tasks', { title: 'Fila do Pessoal', departmentId: pessoal, recurrence: daily })).toMatchObject({ status: 403, body: { message: forbidden } });
    await create(carla, { title: 'Para a Ana', assigneeId: ana.userId, recurrence: daily });
    await create(carla, { title: 'Fila do Fiscal', departmentId: fiscal, recurrence: daily });
    const byEditor = await create(bruno, { title: 'Do Bruno para a Carla', assigneeId: carla.userId, recurrence: daily });
    expect(byEditor.recurrence.canEdit).toBe(true);
    const ofBruno = await create(ana, { title: 'Folha do Pessoal', assigneeId: bruno.userId, dueDate: '2026-10-21', recurrence: { frequency: 'weekly', weekdays: [3] } });

    // Someone else's series in another department: Carla works on the occurrence, not on the series.
    const seen = await carla.get(`/tasks/${ofBruno.id}`);
    expect(seen.body.recurrence.canEdit).toBe(false);
    expect(await carla.patch(`/tasks/${ofBruno.id}`, { title: 'Outra', applyTo: 'series' })).toMatchObject({ status: 403, body: { message: forbidden } });
    expect(await carla.patch(`/tasks/${ofBruno.id}`, { recurrence: null })).toMatchObject({ status: 403 });
    expect((await carla.patch(`/tasks/${ofBruno.id}`, { priority: 'high' })).status).toBe(200);
    // Nor may she hand her own series to another department.
    const own = await create(carla, { title: 'Minha', assigneeId: carla.userId, recurrence: daily });
    expect(await carla.patch(`/tasks/${own.id}`, { assigneeId: bruno.userId, applyTo: 'series' })).toMatchObject({ status: 403, body: { message: forbidden } });
    // With `registry` she may.
    expect((await ana.put(`/workspaces/current/members/${carla.userId}/permissions`, { overrides: { registry: true } })).status).toBe(200);
    expect((await carla.patch(`/tasks/${own.id}`, { assigneeId: bruno.userId, applyTo: 'series' })).status).toBe(200);

    // Occurrences of the registry are changed in "Recorrentes" only.
    const client = await createClient(ana, { tradeName: 'Padaria' });
    const das = await ana.post('/tasks/recurring', { name: 'DAS', departmentId: fiscal, assigneeId: carla.userId, dueDay: 20, regimes: ['simples_nacional'] });
    expect(das.status).toBe(201);
    const [occurrence] = await rows<{ id: string }>(sql`select id from tasks where recurring_task_id = ${das.body.id} and client_id = ${client} order by competence limit 1`);
    const registryMessage = 'Esta tarefa vem de uma tarefa recorrente do cadastro: altere-a em Recorrentes.';
    expect(await ana.patch(`/tasks/${occurrence!.id}`, { recurrence: { frequency: 'monthly' } })).toMatchObject({ status: 422, body: { message: registryMessage } });
    expect(await ana.patch(`/tasks/${occurrence!.id}`, { title: 'X', applyTo: 'series' })).toMatchObject({ status: 422, body: { message: registryMessage } });
    expect((await ana.get(`/tasks/${occurrence!.id}`)).body).toMatchObject({ occurrence: { origin: 'registry' }, recurrence: null });
  });
});
